import json,csv,datetime
from pathlib import Path
from PIL import Image,ImageDraw
root=Path(__file__).resolve().parents[1];rows=json.loads((root/'reports/inventory.json').read_text());manifest=json.loads((root/'public/models/manifest.json').read_text())
lines=['# Asset inventory — Ottawa robotic housing AR','','Audit timezone: **America/Toronto**. Primary window: November 19–20, 2026. Adjacent dates November 18 and 21 were also scanned recursively in Downloads, using creation OR modification date. All 11 GLBs present in Downloads matched; there were no additional creation-only candidates. All 11 candidate GLBs were modified on November 20 (UTC−05:00). No adjacent-day GLBs matched. Generic filename time strings were not treated as authoritative timestamps. Creation times below are filesystem birth times from `stat %W`; these are download/file creation times, not proof of generation time.','','Original files were read only. Project copies preserve filenames and SHA-256 content. Unrelated GLBs outside the date window were not imported. No rejected overhead vacuum lifting bar GLB was found among these candidates; its reference PNG is explicitly excluded from the runtime.','','## Candidate summary','','| Thumbnail / filename | Birth time (Ottawa) | Modified (Ottawa) | MiB | Meshes / triangles | Animations | Visual identification |','|---|---|---|---:|---:|---|---|']
for i,(r,a) in enumerate(zip(rows,manifest)):
 lines.append(f"| [Thumbnail](thumbnails/{i:02}.png) · `{r['filename']}` | {r['creation'] or 'Unavailable'} | {r['modified']} | {r['bytes']/1048576:.2f} | {r['meshes']} / {r['triangles']:,} | None | {a['label']} |")
lines+=['','## Selection and gaps','','- **Main sequence:** frame (sample 073451), solar-roof finished home (sample 074504), arm, rover, palletized materials, excavator, tracked crane and ground. Each was identified from a render of the GLB itself, with the related PNGs as supporting references.','- **Alternatives:** sample 073844 is the simpler finished home; sample 075042 is a second timber frame with slab and lumber. Both remain available in Asset lab and can be assigned in the development editor.','- **Lumber:** the identified GLB is a collection of materials containing lumber, boards and other supplies. A standalone strapped-lumber reference PNG exists, but no matching standalone GLB was found.','- **Partially built house:** two frames were identified; a distinct partially clad house GLB was not found. The timber frame is the unfinished-state fallback.','- **Printer:** identified and optimized, but off by default to avoid clutter and extra transfer. Turning it on loads it on demand.','- **Rejected:** `Robotic Lift Handling Prefab Wall Panel-3.png` shows the overhead vacuum bar. It is not a runtime texture or model and was not used as a substitute for the crawler crane.','- **Ground:** final GLB by modification time, 04:36 Ottawa on November 20. Its integrated fences and two decorative marker poles are preserved. These symbols are not tracking targets.','','## Geometry and preparation','','All candidates have one mesh node, one primitive, one material, no skin/skeleton and no animation clips. Independent movement of booms, buckets, crane wall or arm joints is **not validated**. No joint separation was attempted; whole-object movement preserves the imported shapes. All objects are close to centered around their geometry, but their bottoms lie below Y=0. Their source units are arbitrary.','','Dimensions below use the original glTF scene transforms and its Y-up coordinate system. The application measures again after rotation, centers the horizontal footprint, places the bottom at zero and scales by the longest horizontal dimension. The platform is 3 display units across; other positions are relative display units.','','| Filename | Width X | Height Y | Depth Z | Minimum Y | Center X/Y/Z | Centered? | Ground contact at zero? | Texture dimensions |','|---|---:|---:|---:|---:|---|---|---|---|']
for r in rows:
 b=r['bounds'];dims=b['dimensions'];lines.append(f"| `{r['filename']}` | {dims[0]:.5f} | {dims[1]:.5f} | {dims[2]:.5f} | {b['min'][1]:.5f} | {', '.join(f'{x:.5f}'for x in b['center'])} | {r['centered']} | {r['groundAtY0']} | {', '.join('×'.join(map(str,t['size'])) for t in r['textures'])} |")
lines+=['','All original textures are embedded WebP, with a base-color map and a metallic/roughness map. Originals are opaque, single-sided PBR materials. High polygon counts and 4096² textures are the main mobile risks. The floor is located with a downward ray and upward-facing triangle test; placed assets use their normalized minimum Y plus the independently editable ground offset. This is an approximate contact system, not wheel-by-wheel physics. The editor warns about off-platform origins and intersecting model bounds.','','See [inventory.json](inventory.json) for material values, bounds, node names, texture byte sizes, filenames and hashes. [Contact sheet](model-contact-sheet.jpg) shows every candidate GLB. [Reference sheet](reference-contact-sheet.jpg) is supporting evidence only; the rejected lifting-bar image is excluded.','']
(root/'reports/asset-inventory.md').write_text('\n'.join(lines))
with (root/'reports/asset-inventory.csv').open('w')as f:
 w=csv.writer(f);w.writerow(['filename','creation_ottawa','modified_ottawa','bytes','meshes','triangles','animations','category'])
 for r,a in zip(rows,manifest):w.writerow([r['filename'],r['creation'],r['modified'],r['bytes'],r['meshes'],r['triangles'],len(r['animations']),a['label']])
ps=sorted((root/'reports/thumbnails').glob('*.png'));sheet=Image.new('RGB',(1200,((len(ps)+3)//4)*275),'#e5e9ec');dr=ImageDraw.Draw(sheet)
for i,p in enumerate(ps):
 im=Image.open(p);im.thumbnail((300,225));x=i%4*300;y=i//4*275;sheet.paste(im,(x,y));dr.text((x+6,y+232),manifest[i]['label'][:38],fill='black');dr.text((x+6,y+249),rows[i]['filename'][:42],fill='black')
sheet.save(root/'reports/model-contact-sheet.jpg')
# Refresh measured performance numbers while preserving the reviewed qualitative discussion.
import re
performance=root/'reports/performance.md'
optimization=root/'reports/optimization.json'
if performance.exists() and optimization.exists():
 measurements=json.loads(optimization.read_text());cfg=json.loads((root/'src/config/scene.json').read_text());ids={c['asset']for c in cfg['assets'].values()if c['visible']};mobile=[r for r in measurements if r['quality']=='lite'and r['id']in ids];standard=[r for r in measurements if r['quality']=='standard'and r['id']in ids]
 oldbytes=sum(r['originalBytes']for r in mobile);newbytes=sum(r['optimizedBytes']for r in mobile);oldtri=sum(r['originalTriangles']for r in mobile);newtri=sum(r['triangles']for r in mobile)
 s=performance.read_text();paragraph=f'Default eight loaded models: **{oldbytes/1048576:.2f} MiB → {newbytes/1048576:.2f} MiB**, a {100*(1-newbytes/oldbytes):.1f}% reduction in model transfer size. Geometry: **{oldtri:,} → {newtri:,} triangles** loaded.'
 s=re.sub(r'Default eight loaded models: .*?triangles\*\* loaded\.',paragraph,s)
 table=['| Model | Original MiB / triangles | Mobile MiB / triangles | Standard MiB / triangles |','|---|---:|---:|---:|']
 for a in [r for r in measurements if r['quality']=='lite']:
  b=next(r for r in measurements if r['quality']=='standard'and r['id']==a['id']);table.append(f"| {a['id']} | {a['originalBytes']/1048576:.2f} / {a['originalTriangles']:,} | {a['optimizedBytes']/1048576:.2f} / {a['triangles']:,} | {b['optimizedBytes']/1048576:.2f} / {b['triangles']:,} |")
 start=s.index('| Model |');end=s.index('\n\n',start);s=s[:start]+'\n'.join(table)+s[end:]
 s=re.sub(r'Standard quality defaults total .*? loaded triangles\.',f"Standard quality defaults total {sum(r['optimizedBytes']for r in standard)/1048576:.2f} MiB and {sum(r['triangles']for r in standard):,} loaded triangles.",s);performance.write_text(s)
 testing=root/'reports/testing.md'
 if testing.exists():
  t=testing.read_text();t=re.sub(r'default loads roughly [\d.]+ MiB of GLBs and [\d,]+ triangles',f'default loads roughly {newbytes/1048576:.2f} MiB of GLBs and {newtri:,} triangles',t);testing.write_text(t)
